import { test, expect } from '@playwright/test';

test.describe('Filter Tag Removal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should remove an individual filter tag when x icon is clicked', async ({ page }) => {
    // Apply a filter to generate a tag
    const filterInput = page.getByPlaceholder('Filter by category');
    await filterInput.fill('Electronics');
    const applyButton = page.getByRole('button', { name: 'Apply' });
    await applyButton.click();

    // Verify filter tag is visible
    const filterTag = page.getByText('Electronics');
    await expect(filterTag).toBeVisible();

    // Click the remove icon (x)
    const removeIcon = page.getByRole('button', { name: /remove|close/i });
    await removeIcon.click();

    // Verify filter tag is removed
    await expect(filterTag).not.toBeVisible();

    // Verify search results are updated
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();
  });

  test('should handle removing the last filter tag and clear search results', async ({ page }) => {
    // Apply multiple filters
    const filterInput1 = page.getByPlaceholder('Filter by category');
    await filterInput1.fill('Electronics');
    const applyButton = page.getByRole('button', { name: 'Apply' });
    await applyButton.click();

    const filterInput2 = page.getByPlaceholder('Filter by price');
    await filterInput2.fill('100-500');
    await applyButton.click();

    // Verify both filter tags are visible
    const tag1 = page.getByText('Electronics');
    const tag2 = page.getByText('100-550');
    await expect(tag1).toBeVisible();
    await expect(tag2).toBeVisible();

    // Remove the first filter tag
    const removeIcon1 = page.getByRole('button', { name: /remove|close/i });
    await removeIcon1.click();

    // Verify first tag is removed
    await expect(tag1).not.toBeVisible();
    await expect(tag2).toBeVisible();

    // Remove the second (last) filter tag
    const removeIcon2 = page.getByRole('button', { name: /remove|close/i });
    await removeIcon2.click();

    // Verify both tags are removed
    await expect(tag1).not.toBeVisible();
    await expect(tag2).not.toBeVisible();

    // Verify search results are cleared or reset
    const resultsContainer = page.getByTestId('search-results');
    await expect(resultsContainer).toBeVisible();
    const resultItems = page.getByTestId('result-item');
    const count = await resultItems.count();
    expect(count).toBeGreaterThan(0);
  });
});
